mapper.insert:
WITH requested(code, principal_id) AS ( VALUES
(#{identity.code,typeHandler=com.sca4d.core.spring.persistence.mybatis.TreeCodeTypeHandler$Colon}, #{identity.id})
), created_principals AS ( INSERT INTO iam_principal(id, principal_type, status) SELECT requested.principal_id, #{principalType}, #{status} FROM requested WHERE NOT EXISTS ( SELECT 1 FROM iam_system_identity binding WHERE binding.code = requested.code ) ORDER BY requested.principal_id ON CONFLICT (id) DO NOTHING RETURNING id ) INSERT INTO iam_system_identity(code, principal_id, subject_id) SELECT requested.code, requested.principal_id, #{subjectId} FROM requested INNER JOIN created_principals ON created_principals.id = requested.principal_id ORDER BY requested.code ON CONFLICT DO NOTHING
